/**
 * Writes one reference page per Speculoos entry — a REST operation, or a
 * WebSocket channel — from the IR that `speculoos build` leaves in
 * src/generated/. Each page is a stub: front matter, then <SpeculoosReference>
 * for that one entry.
 *
 * Pages go to a directory per API under docs/api-ref/ (gitignored), which the
 * sidebar lists with `autogenerated`: each page's front matter carries its
 * sidebar label, badge class and position, so nothing else needs writing.
 * Their URLs are the directory's, or `route` where those must differ.
 *
 * A page's own prose — what the spec cannot say — lives in partials beside the
 * hand-written pages, and the config below passes them to an entry by prop.
 *
 * It also writes src/generated/pages.json, each entry's URL by API and entry
 * slug, so a <Schema> in a guide can link to where its type is used in the
 * reference.
 *
 * Standalone rather than a Docusaurus plugin: only the page template is
 * Docusaurus's.
 */
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import {
  type ApiEntry,
  type ApiIR,
  apiEntries,
  entrySlug,
} from "@speculoos/core";

const OUT = "docs/api-ref";

interface Api {
  /** The IR's base name in src/generated/. */
  name: string;
  /** The pages' directory, under docs/api-ref/. Emptied on every run. */
  dir: string;
  /** The pages' URL base, where it is not the directory's. */
  route?: string;
  /**
   * An overview page, index.mdx, for the spec's `info.description`: its title,
   * and its sidebar label where "Overview" would not say which API it is —
   * in a sidebar category shared with others. Only where the directory's URL
   * is the API's own: a `route` shared with other APIs has no index to give.
   */
  overview?: { title: string; label?: string };
  /** By entry slug (`entrySlug`): what a page adds to its entry. */
  entries?: Record<
    string,
    {
      /** The page's file name, where its title's would not do. */
      page?: string;
      /**
       * SpeculoosReference props, each given a partial's content: prop name to
       * module path.
       */
      partials?: Record<string, string>;
    }
  >;
}

const APIS: Api[] = [
  {
    name: "batch",
    dir: "batch",
    overview: { title: "Batch API", label: "Batch API" },
  },
  { name: "mp", dir: "management", overview: { title: "Management API" } },
  {
    name: "realtime",
    dir: "realtime",
    // The page predates the directory: /api-ref/realtime-transcription-websocket.
    route: "/api-ref",
    entries: {
      realtime: {
        page: "realtime-transcription-websocket",
        partials: {
          handshakeExtras:
            "@site/docs/api-ref/_realtime-handshake-responses.mdx",
          after: "@site/docs/api-ref/_realtime-connection-close.mdx",
        },
      },
    },
  },
  {
    name: "agent-stt",
    dir: "agent-stt",
    route: "/api-ref",
    entries: {
      agent: {
        page: "agent-stt-websocket",
        partials: {
          handshakeExtras:
            "@site/docs/api-ref/_agent-stt-handshake-responses.mdx",
          after: "@site/docs/api-ref/_agent-stt-connection-close.mdx",
        },
      },
    },
  },
];

/** "Create a new job" → "create-a-new-job": the live pages' URLs. */
const kebab = (s: string) =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

/** The sidebar badge (src/css/badge.css): the method, or the channel's protocol. */
function badge(entry: ApiEntry): string {
  if (entry.kind === "operation" && entry.operation.kind === "request-response")
    return entry.operation.method;
  return entry.endpoint.protocols[0] ?? "wss";
}

function docsOf(entry: ApiEntry) {
  return entry.kind === "operation"
    ? entry.operation.docs
    : entry.endpoint.docs;
}

/** Its spec title, else what it is: `POST /jobs`. */
function titleOf(entry: ApiEntry): string {
  return (
    docsOf(entry).title ??
    `${badge(entry).toUpperCase()} ${entry.endpoint.address}`
  );
}

/** Front matter wants one: the description's first sentence, else the title. */
function descriptionOf(entry: ApiEntry): string {
  const first = docsOf(entry)
    .description?.split(/(?<=\.)\s|\n/)[0]
    ?.trim();
  return first || `${titleOf(entry)}.`;
}

/** A YAML string: JSON's quoting is valid YAML. */
const yamlString = (s: string) => JSON.stringify(s);

/** `agent-stt` → `agentStt`: an API's IR, as an identifier. */
const identifier = (name: string) =>
  name.replace(/-(\w)/g, (_, c: string) => c.toUpperCase());

/** `handshakeExtras` → `HandshakeExtras`: a partial's component name. */
const component = (prop: string) =>
  prop.charAt(0).toUpperCase() + prop.slice(1);

function page(
  api: Api,
  entry: ApiEntry,
  position: number,
): { file: string; url: string; mdx: string } {
  const slug = entrySlug(entry);
  const config = api.entries?.[slug] ?? {};
  const title = titleOf(entry);
  const partials = Object.entries(config.partials ?? {});
  const props = [
    `ir={${identifier(api.name)}}`,
    `entry=${yamlString(slug)}`,
    ...partials.map(([prop]) => `${prop}={<${component(prop)} />}`),
  ];
  const file = config.page ?? kebab(title);
  const mdx = [
    "---",
    ...(api.route !== undefined
      ? [`slug: ${yamlString(`${api.route}/${file}`)}`]
      : []),
    `title: ${yamlString(title)}`,
    `description: ${yamlString(descriptionOf(entry))}`,
    `sidebar_label: ${yamlString(title)}`,
    `sidebar_class_name: ${yamlString(`${badge(entry)} api-method`)}`,
    `sidebar_position: ${position}`,
    // The entry's own heading, with its URL, is the page title.
    "hide_title: true",
    "hide_table_of_contents: true",
    "custom_edit_url: null",
    "---",
    `{/* Generated by scripts/generate-speculoos-pages.ts from src/generated/${api.name}.ir.json. Do not edit. */}`,
    "",
    'import { SpeculoosReference } from "@site/src/components/Speculoos";',
    `import ${identifier(api.name)} from "@site/src/generated/${api.name}.ir.json";`,
    ...partials.map(
      ([prop, path]) => `import ${component(prop)} from ${yamlString(path)};`,
    ),
    "",
    `<SpeculoosReference ${props.join(" ")} />`,
    "",
  ].join("\n");
  const url = `${api.route ?? `/api-ref/${api.dir}`}/${file}`;
  return { file: `${file}.mdx`, url, mdx };
}

const urls: Record<string, Record<string, string>> = {};
/** An API's overview page: its description, and a link to each entry. */
function overview(
  api: Api,
  ir: ApiIR,
  { title, label = "Overview" }: NonNullable<Api["overview"]>,
): string {
  const first = ir.info.description?.split(/(?<=\.)\s|\n/)[0]?.trim();
  return [
    "---",
    `title: ${yamlString(title)}`,
    `description: ${yamlString(first || `${title} reference.`)}`,
    `sidebar_label: ${yamlString(label)}`,
    "sidebar_position: 0",
    "hide_table_of_contents: true",
    "custom_edit_url: null",
    "---",
    `{/* Generated by scripts/generate-speculoos-pages.ts from src/generated/${api.name}.ir.json. Do not edit. */}`,
    "",
    'import { SpeculoosOverview } from "@site/src/components/Speculoos";',
    `import ${identifier(api.name)} from "@site/src/generated/${api.name}.ir.json";`,
    "",
    `<SpeculoosOverview ir={${identifier(api.name)}} />`,
    "",
  ].join("\n");
}

for (const api of APIS) {
  const ir = JSON.parse(
    readFileSync(`src/generated/${api.name}.ir.json`, "utf8"),
  ) as ApiIR;
  const dir = `${OUT}/${api.dir}`;
  rmSync(dir, { recursive: true, force: true });
  mkdirSync(dir, { recursive: true });
  const entries = apiEntries(ir);
  const unknown = Object.keys(api.entries ?? {}).filter(
    (slug) => !entries.some((e) => entrySlug(e) === slug),
  );
  if (unknown.length > 0)
    throw new Error(`${api.name}: no entry ${unknown.join(", ")}`);
  const files = new Set<string>(["index.mdx"]);
  if (api.overview !== undefined) {
    if (api.route !== undefined)
      throw new Error(`${api.name}: an overview needs the directory's URL`);
    writeFileSync(`${dir}/index.mdx`, overview(api, ir, api.overview));
  }
  const apiUrls: Record<string, string> = {};
  urls[api.name] = apiUrls;
  entries.forEach((entry, i) => {
    const { file, url, mdx } = page(api, entry, i + 1);
    apiUrls[entrySlug(entry)] = url;
    if (files.has(file))
      throw new Error(`${api.name}: two entries would write ${file}`);
    files.add(file);
    writeFileSync(`${dir}/${file}`, mdx);
  });
  console.log(`${api.name}: ${entries.length} pages → ${dir}`);
}
writeFileSync("src/generated/pages.json", `${JSON.stringify(urls, null, 2)}\n`);
